"""New club manager guide: current mobile walkthrough + named UI controls.
Illustrations are instructional diagrams, not fabricated screenshots.
"""

def R(kind, label='', detail='', mark=None, **kwargs):
    return dict(kind=kind, label=label, detail=detail, mark=mark, **kwargs)

